input.command:
cd /home/user/openai-nlogn-wiki/runs/P5/exegenius/tasks; cat > 0002-background.answer.json <<'EOF'
{
  "summary": "The reader is an undergraduate computer scientist: comfortable with asymptotic notation, recurrences and divide-and-conquer, binary and two's-complement arithmetic, integer division with remainder, modular arithmetic, primes and coprimality, sets, bijections and functions, basic vector and matrix algebra, polynomials and complex numbers (including roots of unity), and basic multitape Turing machines with linear scans. The reader has seen schoolbook and Karatsuba multiplication and probably an introductory FFT in an algorithms course, but has not studied abstract algebra (rings, groups, tensor products), finite fields beyond bit arithmetic, numerical analysis of rounding, or the specialist theory of fast integer multiplication, so the wiki must explain those.",
  "known": [
    {
      "name": "Logarithms, floors and ceilings",
      "aliases": ["log", "lg", "log base 2", "floor", "ceiling", "⌊x⌋", "⌈x⌉"],
      "gloss": "The base-2 logarithm and the floor and ceiling functions that round a real number down or up to an integer, used to count the bits of a number."
    },
    {
      "name": "Binary representation and integer arithmetic",
      "aliases": ["binary numerals", "bit strings", "radix representation", "base-b digits", "bits", "carries"],
      "gloss": "Writing a nonnegative integer as a bit string or as digits in a radix, with addition, subtraction and schoolbook multiplication on digits and carries."
    },
    {
      "name": "Division with remainder",
      "aliases": ["quotient and remainder", "Euclidean division", "integer division"],
      "gloss": "For integers a and b>0 there are unique q=⌊a/b⌋ and r=a−bq with 0≤r<b."
    },
    {
      "name": "Modular arithmetic",
      "aliases": ["congruences", "residues", "mod q", "integers modulo q", "Z/qZ", "residue classes"],
      "gloss": "Arithmetic on integers up to equality of remainders modulo a fixed modulus, including addition, multiplication and wraparound."
    },
    {
      "name": "Primes, divisibility and coprimality",
      "aliases": ["prime numbers", "relatively prime", "pairwise coprime", "gcd", "greatest common divisor", "coprime"],
      "gloss": "Prime numbers, divisibility, and integers sharing no common factor (gcd 1), including that a unit modulo a prime power is a number not divisible by the prime."
    },
    {
      "name": "Sets, functions and permutations",
      "aliases": ["bijection", "permutation of a set", "subsets", "intersection", "cardinality", "indicator vector", "Cartesian product"],
      "gloss": "Finite sets, subsets with intersection and size, functions, and permutations as bijections of a finite set, and products of index sets."
    },
    {
      "name": "Matrices and linear maps",
      "aliases": ["matrix-vector product", "identity matrix", "permutation matrix", "matrix inverse", "linear transformation", "vector spaces"],
      "gloss": "Vectors as columns of numbers, matrices acting on them by multiplication and composing by matrix product, with identity, inverse and permutation matrices."
    },
    {
      "name": "XOR and arithmetic over F₂",
      "aliases": ["exclusive or", "mod 2 addition", "bitwise XOR", "GF(2)", "parity", "Hamming weight", "popcount"],
      "gloss": "Addition of bits modulo 2 (bitwise XOR), with parity and the number of one bits in a string."
    },
    {
      "name": "Asymptotic notation beyond big-O",
      "aliases": ["Θ", "Ω", "little-o", "Theta notation", "polylogarithmic factor", "poly log"],
      "gloss": "Tight and lower bounds Θ and Ω, little-o, and absorbing polylogarithmic factors and smaller powers of a growing parameter into a larger one."
    },
    {
      "name": "Recurrences and divide and conquer",
      "aliases": ["recurrence relation", "master theorem", "recursion tree", "geometric series", "divide-and-conquer"],
      "gloss": "Bounding the cost of a recursive algorithm by solving a recurrence over subproblem sizes, including unrolling it and summing a geometric series."
    },
    {
      "name": "Schoolbook and Karatsuba multiplication",
      "aliases": ["grade-school multiplication", "quadratic multiplication", "Karatsuba", "O(n^2) multiplication"],
      "gloss": "The O(n²) digit-by-digit algorithm for multiplying n-bit integers and the divide-and-conquer improvement with three half-size products."
    },
    {
      "name": "Fast Fourier transform as an algorithm",
      "aliases": ["FFT", "Cooley–Tukey", "Cooley-Tukey algorithm", "fast polynomial multiplication by FFT", "evaluation and interpolation"],
      "gloss": "The O(N log N) divide-and-conquer evaluation of a polynomial at N-th roots of unity and its use to multiply polynomials by pointwise products and an inverse transform."
    },
    {
      "name": "Inequalities for error bounds",
      "aliases": ["triangle inequality", "absolute value bounds", "modulus bound", "error accumulation", "rounding error"],
      "gloss": "Bounding a sum or product of approximations by adding or multiplying the individual absolute errors, and the idea that rounding to the nearest integer succeeds if the error is below 1/2."
    },
    {
      "name": "Lexicographic order and mixed-radix indices",
      "aliases": ["row-major order", "multi-dimensional arrays", "array indexing", "mixed radix", "lexicographic address order"],
      "gloss": "Storing a multi-dimensional array in a linear sequence by ordering index tuples lexicographically, so the position is a mixed-radix number."
    },
    {
      "name": "Two's-complement and truncation",
      "aliases": ["signed integers", "round toward zero", "truncate", "fixed-point numbers"],
      "gloss": "Representing signed integers in two's complement and discarding low-order bits to round a number toward zero."
    }
  ]
}
EOF
cd ../..; exegenius submit 0002-background

